#!/usr/bin/env node
/**
 * Gera `supabase/functions/mcp/index.ts` (bundle Deno do MCP) de forma correta também no Windows.
 *
 * Por que este script existe
 * --------------------------
 * O plugin Vite do @lovable.dev/mcp-js monta o wrapper com o caminho ABSOLUTO da entrada
 * (ex.: `C:\...\src\lib\mcp\index.ts`) e usa um resolver que externaliza qualquer caminho
 * que NÃO comece com "." ou "/" como `npm:<caminho>`. No Windows isso produz
 * `import mcp from "npm:C:\...\src\lib\mcp\index.ts"` — inválido no Deno — e o bundle
 * publicado fica sem as tools.
 *
 * Este script reproduz o MESMO build do plugin (esbuild, banner, externalização de bare
 * specifiers como `npm:`), mudando apenas uma coisa: o especificador da entrada é RELATIVO
 * (`./src/lib/mcp/index.ts`), que o esbuild resolve e empacota normalmente.
 *
 * Uso: node scripts/build-mcp-deno-bundle.mjs [--check]
 *   --check  não escreve; falha (exit 1) se o arquivo commitado estiver diferente do gerado.
 */
import { readFileSync, writeFileSync, existsSync, readdirSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

const projectRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const entryRel = "src/lib/mcp/index.ts";
const functionName = "mcp";
const outputFile = join(projectRoot, "supabase", "functions", functionName, "index.ts");
const checkOnly = process.argv.includes("--check");

const BANNER =
  "// AUTO-GENERATED by @lovable.dev/mcp-js — do not edit. Regenerated by the Vite plugin.\n" +
  "// To take ownership, delete this banner line; the plugin then leaves the file alone.";

function findEsbuild() {
  const candidates = [
    join(projectRoot, "node_modules", "esbuild"),
    join(projectRoot, "node_modules", ".pnpm", "node_modules", "esbuild"),
  ];
  const store = join(projectRoot, "node_modules", ".pnpm");
  if (existsSync(store)) {
    for (const name of readdirSync(store)) {
      if (name.startsWith("esbuild@")) candidates.push(join(store, name, "node_modules", "esbuild"));
    }
  }
  for (const candidate of candidates) {
    const manifest = join(candidate, "lib", "main.js");
    if (existsSync(manifest)) return manifest;
  }
  throw new Error("esbuild não encontrado (esperado em node_modules ou no store do pnpm).");
}

function readJson(path, fallback) {
  try {
    return JSON.parse(readFileSync(path, "utf8"));
  } catch {
    return fallback;
  }
}

function readInlineEnv() {
  const env = {};
  for (const file of [".env", ".env.local", ".env.production"]) {
    const path = join(projectRoot, file);
    if (!existsSync(path)) continue;
    for (const line of readFileSync(path, "utf8").split(/\r?\n/)) {
      const match = /^\s*(VITE_[A-Za-z0-9_]+)\s*=\s*(.*)\s*$/.exec(line);
      if (!match) continue;
      env[match[1]] = match[2].replace(/^["']|["']$/g, "");
    }
  }
  return env;
}

const pkg = readJson(join(projectRoot, "package.json"), {});
const versions = { ...pkg.peerDependencies, ...pkg.devDependencies, ...pkg.dependencies };
const mcpJsVersion =
  readJson(join(projectRoot, "node_modules", "@lovable.dev", "mcp-js", "package.json"), {}).version ??
  versions["@lovable.dev/mcp-js"];
const inlineEnv = readInlineEnv();

const { build } = await import(pathToFileURL(findEsbuild()).href);

const wrapper = `import mcp from ${JSON.stringify("./" + entryRel)};
import { createSupabaseHandler } from "@lovable.dev/mcp-js/stacks/supabase";
Deno.serve(createSupabaseHandler(mcp, { functionName: ${JSON.stringify(functionName)} }));
`;

function npmSpecifierFor(bare) {
  const pkgName = bare.startsWith("@") ? bare.split("/").slice(0, 2).join("/") : bare.split("/")[0];
  const subpath = bare.slice(pkgName.length);
  if (pkgName === "@lovable.dev/mcp-js") return `npm:${pkgName}@${mcpJsVersion}${subpath}`;
  const range = versions[pkgName];
  const version = range && /^[\dv^~>=]|^latest$/.test(range) ? range : undefined;
  return version ? `npm:${pkgName}@${version}${subpath}` : `npm:${pkgName}${subpath}`;
}

const externalizeBareAsNpm = {
  name: "lovable-mcp-externalize-bare-as-npm",
  setup(pluginBuild) {
    pluginBuild.onResolve({ filter: /.*/ }, (args) => {
      const p = args.path;
      if (p.startsWith(".") || p.startsWith("/")) return null;
      if (/^(npm|node|jsr|https?|data):/.test(p)) return { path: p, external: true };
      return { path: npmSpecifierFor(p), external: true };
    });
  },
};

const defines = { "import.meta.env": JSON.stringify(inlineEnv) };
for (const [key, value] of Object.entries(inlineEnv)) {
  if (/^[A-Za-z_$][\w$]*$/.test(key)) defines[`import.meta.env.${key}`] = JSON.stringify(value);
}

const result = await build({
  stdin: {
    contents: wrapper,
    resolveDir: projectRoot,
    sourcefile: "lovable-mcp-supabase-entry.ts",
    loader: "ts",
  },
  bundle: true,
  write: false,
  metafile: true,
  format: "esm",
  platform: "neutral",
  target: "esnext",
  absWorkingDir: projectRoot,
  logLevel: "silent",
  define: defines,
  plugins: [externalizeBareAsNpm],
});

const out = result.outputFiles[0]?.text ?? "";
const entryAbs = resolve(projectRoot, entryRel);
const code =
  `${BANNER}\n// supabase function: ${functionName}\n// Bundled from ${relative(projectRoot, entryAbs).split(sep).join("/")} by @lovable.dev/mcp-js.\n` +
  out;

const invalid = [...code.matchAll(/npm:[A-Za-z]:[^"']*/g)].map((match) => match[0]);
if (invalid.length > 0) {
  console.error("BUNDLE_INVALID: caminho local externalizado ->", invalid.slice(0, 3));
  process.exit(1);
}
const toolNames = [
  ...new Set([...code.matchAll(/name:\s*"([a-z][a-z0-9_]*)",\s*\n\s*title:/g)].map((match) => match[1])),
].sort();
const toolCount = toolNames.length;

if (checkOnly) {
  const current = existsSync(outputFile) ? readFileSync(outputFile, "utf8") : "";
  if (current !== code) {
    console.error(`BUNDLE_STALE: ${relative(projectRoot, outputFile)} difere do bundle gerado (${toolCount} tools). Rode: node scripts/build-mcp-deno-bundle.mjs`);
    process.exit(1);
  }
  console.log(`BUNDLE_CHECK_PASS tools=${toolCount} bytes=${code.length}`);
  process.exit(0);
}

writeFileSync(outputFile, code, "utf8");
console.log(
  `BUNDLE_WRITTEN ${relative(projectRoot, outputFile).split(sep).join("/")} tools=${toolCount} bytes=${code.length} mcpJs=${mcpJsVersion}`,
);
console.log(toolNames.join(", "));
